const teams={AIK:{name:'AIK',city:'Stockholm',arena:'Avicii Arena',pos:1,points:38,gp:15,last:'4–1 mot Vimmerby',lat:59.2936,lon:18.0832},LIF:{name:'Leksands IF',city:'Leksand',arena:'Tegera Arena',pos:2,points:35,gp:15,last:'5–2 mot Karlskoga',lat:60.733,lon:14.996},MODO:{name:'MoDo Hockey',city:'Örnsköldsvik',arena:'Hägglunds Arena',pos:3,points:31,gp:15,last:'3–0 mot Nybro',lat:63.290,lon:18.716},KAL:{name:'Kalmar HC',city:'Kalmar',arena:'Hatstore Arena',pos:4,points:30,gp:15,last:'4–2 mot Östersund',lat:56.663,lon:16.356},SSK:{name:'Södertälje SK',city:'Södertälje',arena:'Scaniarinken',pos:5,points:28,gp:15,last:'3–2 mot Mora',lat:59.195,lon:17.568},IKO:{name:'IK Oskarshamn',city:'Oskarshamn',arena:'Be-Ge Hockey Center',pos:6,points:26,gp:16,last:'6–3 mot Visby/Roma',lat:57.265,lon:16.448},MORA:{name:'Mora IK',city:'Mora',arena:'Smidjegrav Arena',pos:7,points:21,gp:15,last:'2–3 mot Södertälje',lat:61.005,lon:14.543},AIS:{name:'Almtuna IS',city:'Uppsala',arena:'Upplands Bilforum Arena',pos:8,points:20,gp:15,last:'1–0 mot Västerås',lat:59.858,lon:17.645},BIK:{name:'BIK Karlskoga',city:'Karlskoga',arena:'Nobelhallen',pos:9,points:18,gp:15,last:'2–5 mot Leksand',lat:59.326,lon:14.524},VIK:{name:'Västerås IK',city:'Västerås',arena:'ABB Arena Nord',pos:10,points:17,gp:15,last:'0–1 mot Almtuna',lat:59.631,lon:16.531},OIK:{name:'Östersunds IK',city:'Östersund',arena:'Östersund Arena',pos:11,points:17,gp:15,last:'2–4 mot Kalmar',lat:63.190,lon:14.635},NYB:{name:'Nybro Vikings',city:'Nybro',arena:'Liljas Arena',pos:12,points:13,gp:15,last:'0–3 mot MoDo',lat:56.744,lon:15.907},VIM:{name:'Vimmerby HC',city:'Vimmerby',arena:'VBO Arena',pos:13,points:12,gp:14,last:'1–4 mot AIK',lat:57.666,lon:15.855},VRH:{name:'Visby/Roma HK',city:'Visby',arena:'Visby Ishall',pos:14,points:9,gp:15,last:'3–6 mot Oskarshamn',lat:57.638,lon:18.294}};
const p=new URLSearchParams(location.search),a=p.get('a')||'AIK',b=p.get('b')||'LIF',ta=teams[a],tb=teams[b],root=document.querySelector('#ha-content');
function teamCard(code,t){return `<div class="ha-team"><div class="ha-shield">${code}</div><h1>${t.name}</h1><p>${t.city}</p></div>`}function tableRow(code,t){return `<div class="ha-row"><span class="ha-mini">${code}</span><div><b>${t.name}</b><small>${t.gp} matcher · ${t.points} poäng</small></div><strong>#${t.pos}</strong></div>`}
function render(){root.innerHTML=`<section class="ha-hero"><p class="eyebrow">HOCKEYALLSVENSKAN · 19.00</p><div class="ha-match">${teamCard(a,ta)}<div class="ha-vs">MOT</div>${teamCard(b,tb)}</div><p class="ha-date">Fredag 30 oktober 2026 · ${ta.arena}</p></section><section class="ha-grid"><article class="ha-card"><p class="eyebrow dark">TABELLEN JUST NU</p><h2>Ligaplacering</h2>${tableRow(a,ta)}${tableRow(b,tb)}<a href="https://hockeyallsvenskan.se/pages/stats" target="_blank">Se hela tabellen ↗</a></article><article class="ha-card"><p class="eyebrow dark">SENASTE RESULTAT</p><h2>Formbesked</h2><div class="form-row"><b>${ta.name}</b><span>${ta.last}</span></div><div class="form-row"><b>${tb.name}</b><span>${tb.last}</span></div><p class="verified">Uppdaterat efter matcherna 28 oktober.</p></article></section><section class="sweden-section"><div><p class="eyebrow">VAR LAGEN FINNS</p><h2>Från ${ta.city}<br>till ${tb.city}</h2><p class="arena"><b>${ta.arena}</b>${ta.city}</p><p class="arena"><b>${tb.arena}</b>${tb.city}</p></div><div id="ha-map" class="ha-real-map" role="img" aria-label="Interaktiv Sverigekarta med lagens hemorter"></div></section>`;initMap()}
function initMap(){const map=L.map('ha-map',{scrollWheelZoom:false});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap'}).addTo(map);const icon=(color,code)=>L.divIcon({className:'ha-map-icon',html:`<span style="--pin:${color}">${code}</span>`,iconSize:[50,50],iconAnchor:[25,25]});const m1=L.marker([ta.lat,ta.lon],{icon:icon('#ff5b35',a)}).addTo(map).bindPopup(`<b>${ta.name}</b><br>${ta.arena}<br>${ta.city}`),m2=L.marker([tb.lat,tb.lon],{icon:icon('#b9ffcf',b)}).addTo(map).bindPopup(`<b>${tb.name}</b><br>${tb.arena}<br>${tb.city}`);L.polyline([[ta.lat,ta.lon],[tb.lat,tb.lon]],{color:'#0d6b50',weight:3,dashArray:'9 10'}).addTo(map);map.fitBounds(L.latLngBounds([m1.getLatLng(),m2.getLatLng()]).pad(.45),{maxZoom:7});setTimeout(()=>map.invalidateSize(),80)}render();
